describe('cvScreen — the cv penalty, solved rather than swept', () => {
  /** The configuration a screen is measured against, with the other terms held off. */
  const WEIGHTS = { logWeight: 0, latWeight: 0, poolWeight: 0, temporalWeight: 0 } as const;

  it('reproduces the dump’s own rank-1 at w = 0, which is the instrument’s self-check', () => {
    // The base of every affine case is `shippedScores`, so the number of cases satisfied at
    // zero weight IS the number the dump's own ranking got right. An instrument that scored a
    // different ranking than the run it reads would report a gain against itself.
    const cases = [
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.9, 0.5],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-0',
      }),
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    expect(cvScreen(cases, WEIGHTS).solved.window.satisfied).toBe(1);
  });

  it('finds the weight at which a lower-cv root is promoted', () => {
    // `ts-svc-0` is the root and the less anomalous service; the engine's rank-1 is the more
    // anomalous, less stable one. The base gap is the METRIC term's own, `log1p(1) − log1p(0)`,
    // because the metric term is a rank normalisation rather than the raw anomaly — and the
    // promotion weight is that gap over the slope gap exactly, so this pins the closed form
    // instead of a sampled approximation of it.
    const cases = [
      cvCase({
        cvs: [0.2, 0.8],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const screen = cvScreen(cases, WEIGHTS);
    expect(screen.solved.gain).toBe(1);
    expect(screen.solved.gained).toEqual(['dp-1']);
    expect(screen.solved.window.satisfied).toBe(0);
    expect(screen.solved.ship).toBeCloseTo(Math.log1p(1) / 0.75, 9);
    expect(screen.gainTypes).toEqual([{ key: 'JVMMemoryStress', cases: 1 }]);
  });

  it('ships 0 and gains nothing when the term cannot change an order', () => {
    // No spread to weigh: a positive weight would be a configuration change with no measured
    // effect, and the register records a weight that buys nothing as a defect.
    const cases = [
      cvCase({
        cvs: [0.4, 0.4],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const screen = cvScreen(cases, WEIGHTS);
    expect(screen.solved.gain).toBe(0);
    expect(screen.solved.ship).toBe(0);
    expect(screen.solved.lostAtShip).toBe(0);
  });

  it('loses no case that was correct at zero, on either shape', () => {
    const cases = [
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.9, 0.5],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-0',
      }),
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    for (const screen of cvShapeMenu(cases, WEIGHTS)) {
      expect(screen.solved.lostAtShip).toBe(0);
      // The window protects the case that was right: the gain is one, and the loss is measured
      // rather than inferred from the cap.
      expect(screen.solved.gain).toBe(1);
    }
  });

  it('protects a population that does not depend on the shape', () => {
    // A gain with no population is unreadable: `gain 4` means one thing out of 3 correct cases and
    // another out of 700. TWO of the three counts come from the BASE, which neither shape touches:
    // the case set and the number the shipped score gets right. `correct at 0` is also the
    // instrument's fidelity line, because the base IS the shipped score.
    const cases = [
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.9, 0.5],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-0',
      }),
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const menu = cvShapeMenu(cases, WEIGHTS);
    const flip = menu[0]!.solved.window;
    const rank = menu[1]!.solved.window;
    expect(flip.cases).toBe(rank.cases);
    expect(flip.satisfied).toBe(rank.satisfied);
    expect(flip.unreachable).toBe(rank.unreachable);
    // One of the two cases is correct at `w = 0` — the one whose root leads on the metric term.
    expect(flip.cases).toBe(2);
    expect(flip.satisfied).toBe(1);
    expect(flip.unreachable).toBe(0);
    expect(formatCvMenuReport(menu, WEIGHTS)).toContain('correct at 0');
    expect(formatCvScreenReport(menu[0]!, WEIGHTS)).toContain('correct at 0 1');
  });

  it('does NOT claim the third count is shape-independent, because it is not', () => {
    // `unreachable` is a count of cases whose ADMISSIBLE SET is empty, and emptiness is decided by
    // the slopes — so the two shapes can disagree on it while agreeing on the population, and one
    // shape's number printed above a two-row table is a number about neither row. Measured on run
    // 35107871516: `flip` 569 against `rank` 526 over the same 1422 cases. The fixture below is a
    // three-service case where the spacing the two shapes give the same cv ORDER decides whether
    // the root's interval exists at all, which is the smallest input that can separate them.
    const cases = parseDiagnosticDump(
      dump({
        datapack: 'dp-shape-dependent',
        groundTruthServices: ['ts-svc-0'],
        services: [
          serviceLine({
            serviceId: 'ts-svc-0',
            selfAnomaly: 0.4,
            metricOutcomes: [
              { label: 'cpu', outcome: 'kept', score: 1, breakdown: breakdownOf(0.6) },
            ],
          }),
          serviceLine({
            serviceId: 'ts-svc-1',
            selfAnomaly: 0.1,
            metricOutcomes: [
              { label: 'cpu', outcome: 'kept', score: 1, breakdown: breakdownOf(0.1) },
            ],
          }),
          serviceLine({
            serviceId: 'ts-svc-2',
            selfAnomaly: 0.7,
            metricOutcomes: [
              { label: 'cpu', outcome: 'kept', score: 1, breakdown: breakdownOf(0.9) },
            ],
          }),
        ],
        topPredictions: ['ts-svc-2'],
      }),
    );
    const menu = cvShapeMenu(cases, WEIGHTS);
    const flip = menu.find((screen) => screen.shape === 'flip')!;
    const rank = menu.find((screen) => screen.shape === 'rank')!;

    expect(flip.solved.window.satisfied).toBe(rank.solved.window.satisfied);
    expect(flip.solved.window.unreachable).toBe(1);
    expect(rank.solved.window.unreachable).toBe(0);

    const report = formatCvMenuReport(menu, WEIGHTS);
    // Each shape's own count, named — and never one shape's number standing for the dump.
    expect(report).toContain('flip 1');
    expect(report).toContain('rank 0');
    expect(report).not.toContain('unreachable at every weight 1\n');
  });
});

describe('formatCvMenuReport — availability first, then one row per shape', () => {
  const WEIGHTS = { logWeight: 0, latWeight: 0, poolWeight: 0, temporalWeight: 0 } as const;

  it('states how much of the dump carries a composition before any window', () => {
    // Order is the point, not decoration: a gain of 0 caused by an absent measurement and a
    // gain of 0 caused by a term that cannot help read identically in a row, and only the
    // availability line tells them apart.
    const cases = [
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const report = formatCvMenuReport(cvShapeMenu(cases, WEIGHTS), WEIGHTS);
    const lines = report.split('\n');
    const availability = lines.findIndex((line) => line.includes('services carrying'));
    const firstWindow = lines.findIndex((line) => line.includes('window:'));
    expect(availability).toBeGreaterThan(-1);
    expect(firstWindow).toBeGreaterThan(availability);
    // Both services carry a composition, and the case is the one the term can reorder.
    expect(report).toContain('2/2');
    expect(report).toContain('can act on 1');
  });

  it('names every declared shape, with its own solved window', () => {
    const cases = [
      cvCase({
        cvs: [0.2, 0.8],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const report = formatCvMenuReport(cvShapeMenu(cases, WEIGHTS), WEIGHTS);
    for (const shape of CV_SHAPES) expect(report).toContain(shape);
    expect(report).toContain('gain 1');
  });

  it('says the term is inert rather than printing a window over nothing', () => {
    // A dump that carries no case this can act on. The share is `n/a` rather than a division by
    // an empty population, and no `window:` line is printed at all: a gain of 0 here is a data
    // gap, and a window row would present it as a verdict on the shape.
    const cases = parseDiagnosticDump(
      dump({ groundTruthServices: [], services: [], topPredictions: [] }),
    );
    const menu = formatCvMenuReport(cvShapeMenu(cases, WEIGHTS), WEIGHTS);
    expect(menu).toContain('0/0 (n/a)');
    expect(menu).toContain('the term is INERT on this dump');
    expect(menu).not.toContain('window:');
    expect(formatCvScreenReport(cvScreen(cases, WEIGHTS), WEIGHTS)).toContain(
      'the term is INERT on this dump',
    );
  });

  it('prints the binder for a finite cap even when nothing is gained', () => {
    // A row of zeros with no mechanism is a verdict nobody can refute. One case is correct at
    // zero and caps the weight; the other's root is behind on BOTH terms, so no weight can ever
    // fix it — and the report has to say which of the two produced the zero.
    const cases = [
      cvCase({
        datapack: 'dp-cap',
        cvs: [0.8, 0.2],
        anomalies: [0.9, 0.5],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-0',
      }),
      cvCase({
        datapack: 'dp-lost',
        cvs: [0.8, 0.2],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const single = formatCvScreenReport(cvScreen(cases, WEIGHTS), WEIGHTS);
    expect(single).toContain('no admissible gain');
    // The cap is `log1p(1) / 0.75` — the weight at which `dp-cap`'s correct root is overtaken.
    expect(single).toContain('cap bound by dp-cap');
    expect(single).toContain(`cap ${(Math.log1p(1) / 0.75).toFixed(6)}`);
    const menu = formatCvMenuReport(cvShapeMenu(cases, WEIGHTS), WEIGHTS);
    // Both shapes bind on the SAME pair, at weights that differ only through the slope's shape —
    // `log1p(1)/0.75` for the magnitude and `log1p(1)/1` for the order.
    expect(menu).toContain('bound by dp-cap');
    expect(menu).toContain(`cap ${(Math.log1p(1) / 0.75).toFixed(6)}`);
    expect(menu).toContain(`cap ${Math.log1p(1).toFixed(6)}`);
    expect(menu).toContain('no shape in this menu has an admissible gain at any weight');
  });
});

describe('cvScreen — the base is the engine that ran, not a two-term blend', () => {
  it('satisfies at w = 0 a case the LATENCY term decided', () => {
    // `shippedScores` is the base, and the latency and pool terms are in it. A screen built on
    // the parsed anomaly alone would reconstruct a ranking nobody had and then report a "gain"
    // against a run that never produced it. Measured, not argued: the root below wins on the
    // latency term and LOSES on the metric term, so the two configurations disagree about which
    // case is satisfied at zero.
    //
    // A field of 26, because one term can only be shown to decide a ranking where the other
    // leaves room: with two candidates the metric term's top-to-bottom gap is `log1p(1)`, which
    // the latency term's own maximum (`latWeight × 1`) cannot cross.
    const FILLERS = 24;
    const text = dump({
      groundTruthServices: ['ts-late'],
      services: [
        serviceLine({
          serviceId: 'ts-hot',
          selfAnomaly: 0.9,
          latRise: 1,
          latEdges: 2,
          dominant: 'cpu',
          metricOutcomes: [
            { label: 'cpu', outcome: 'kept', score: 1, breakdown: breakdownOf(0.1) },
          ],
        }),
        serviceLine({
          serviceId: 'ts-late',
          selfAnomaly: 0.5,
          latRise: 12,
          latEdges: 2,
          dominant: 'cpu',
          metricOutcomes: [
            { label: 'cpu', outcome: 'kept', score: 1, breakdown: breakdownOf(0.6) },
          ],
        }),
        ...Array.from({ length: FILLERS }, (_, i) =>
          serviceLine({
            serviceId: `ts-filler-${String(i).padStart(2, '0')}`,
            selfAnomaly: 0.49 - i / 100,
          }),
        ),
      ],
      topPredictions: ['ts-late'],
    });
    const cases = parseDiagnosticDump(text);
    expect(
      cvScreen(cases, { logWeight: 0, poolWeight: 0, temporalWeight: 0 }).solved.window.satisfied,
    ).toBe(1);
    expect(
      cvScreen(cases, { logWeight: 0, latWeight: 0, poolWeight: 0, temporalWeight: 0 }).solved
        .window.satisfied,
    ).toBe(0);
  });
});

describe('parseDiagnosticDump — the CI log transport prefix', () => {
  /** The prefix GitHub's job log puts on every line of stdout. */
  const TAG = '2026-09-16T14:24:33.7040161Z ';

  /** The same dump as a download gives it: a BOM, then a timestamp on every line. */
  function asDownloaded(text: string): string {
    return `\uFEFF${text
      .split('\n')
      .map((line) => TAG + line)
      .join('\n')}`;
  }

  const SOURCE = () =>
    dump({
      groundTruthServices: ['ts-order-service'],
      services: [
        serviceLine({
          serviceId: 'ts-order-service',
          selfAnomaly: 0.9,
          logScore: 2,
          failedEdge: 0.4,
          failedEdgeRecords: 3,
          latRise: 4,
          latEdges: 2,
          onset: 1200,
          logic: 8,
          http: 5,
          both: 2,
          dominant: 'cpu',
          metricOutcomes: [
            { label: 'cpu', outcome: 'kept', score: 1, breakdown: breakdownOf(0.3) },
          ],
        }),
        serviceLine({ serviceId: 'ts-payment-service', selfAnomaly: 0.4 }),
      ],
      topPredictions: ['ts-order-service', 'ts-payment-service'],
      injectTimeMs: 1_700_000_000_000,
    });

  it('reads a log exactly as a download gives it, with a timestamp on every line', () => {
    // The module's contract says the parser "can also be pointed at a downloaded CI artifact", and
    // a download is NOT the text the engine wrote: GitHub prefixes every line of stdout with a
    // timestamp. The dump's grammar is column-anchored (`DIAG` at column 0, two spaces for a
    // service, four for a metric), so an unstripped log parses to ZERO cases — a silent data gap
    // that reads exactly like a run that produced nothing.
    const clean = parseDiagnosticDump(SOURCE());
    const downloaded = parseDiagnosticDump(asDownloaded(SOURCE()));
    expect(downloaded).toEqual(clean);
    // Pinned field by field, so the equality above cannot be satisfied by two empty parses: the
    // header, the indented rows and the four-space metric lines each have their own anchor, and
    // one surviving anchor would not prove the others did.
    expect(downloaded).toHaveLength(1);
    expect(downloaded[0]!.injectTimeMs).toBe(1_700_000_000_000);
    expect(downloaded[0]!.services).toHaveLength(2);
    expect(downloaded[0]!.services[0]!.decisiveOutcome?.breakdown?.cv).toBeCloseTo(0.3, 10);
    expect(downloaded[0]!.prediction).toEqual(['ts-order-service', 'ts-payment-service']);
  });

  it('strips a BOM that the transport puts before the first line of a CHUNK', () => {
    // The BOM is not only at the head of the file: GitHub writes one before the first line of every
    // output chunk, so a BOM can sit MID-LOG — and because it sits BEFORE the timestamp, a strip that
    // removes BOMs only at the head leaves that line with neither its BOM nor its timestamp gone, so
    // it matches no pattern at all. Measured on run 35107871516: 13 of 1422 blocks carry one on a
    // service row, each losing a row and being DROPPED for a count mismatch — 0.9% of the population,
    // 10 of them cases the run got right.
    const text = SOURCE();
    const lines = text.split('\n');
    const row = lines.findIndex((line) => line.startsWith('  ts-payment-service'));
    expect(row).toBeGreaterThan(-1);
    lines[row] = `\uFEFF${TAG}${lines[row]}`;

    const cases = parseDiagnosticDump(lines.join('\n'));
    expect(cases).toHaveLength(1);
    expect(cases[0]!.services).toHaveLength(2);
    expect(cases[0]!.services.map((s) => s.serviceId)).toContain('ts-payment-service');
  });

  it('leaves a dump that was already clean untouched', () => {
    // Both forms are on this repo's disk — the saved fixtures are the stripped form and a raw job
    // log is the tagged one — so the strip has to be idempotent rather than a one-way filter.
    const clean = SOURCE();
    expect(parseDiagnosticDump(clean)).toEqual(parseDiagnosticDump(clean));
    expect(parseDiagnosticDump(clean)[0]!.services).toHaveLength(2);
  });
});

describe('--cv-screen wiring', () => {
  it('parses --cv-screen into a section that carries the run’s configuration', () => {
    const options = parseAnalyzeArgs(['--dump', 'd', '--cv-screen', '--log-weight', '1']);
    if (options.kind !== 'dump') throw new Error('expected a dump mode');
    expect(options.sections.map((section) => section.kind)).toEqual(['cvScreen']);
  });

  it('renders every section the parser accepts through the dispatcher', () => {
    // The census sections had no end-to-end test, which left the dispatcher's own arms — the one
    // place where a flag that parses and validates can still render NOTHING — outside the gate.
    // Asserted per section rather than in aggregate: "the report is non-empty" passes on the
    // anomaly-shape appendix that every dump mode prints.
    const cases = parseDiagnosticDump(
      dump({
        groundTruthServices: ['ts-order-service'],
        services: [serviceLine({ serviceId: 'ts-order-service', selfAnomaly: 0.9 })],
        topPredictions: ['ts-order-service'],
      }),
    );
    const expected: readonly (readonly [string, string])[] = [
      ['--separator-screen', 'Separator census'],
      ['--guard-census', 'Metric-guard census'],
    ];
    for (const [flag, heading] of expected) {
      const options = parseAnalyzeArgs(['--dump', 'd', flag, '--log-weight', '0']);
      if (options.kind !== 'dump') throw new Error('expected a dump mode');
      expect(formatAnalyzeSections(cases, 'd', options)).toContain(heading);
    }
  });

  it('is enrolled in the weight guard as well as in the dispatch', () => {
    // A section needs TWO registrations, and the pair is what this asserts: a flag wired into the
    // dispatch but not into the guard would reconstruct `shippedScores` at a weight nobody chose,
    // and the report would describe a ranking the run never had while looking like a measurement.
    expect(() => parseAnalyzeArgs(['--dump', 'd', '--cv-screen'])).toThrow(/--log-weight/);
  });

  it('renders through the section dispatcher, not only through its own formatter', () => {
    // The dispatch is the third registration: a flag in the guard and the switch set but absent
    // from `analyzeSectionText` is accepted, validated, and silently renders nothing.
    const cases = [
      cvCase({
        cvs: [0.2, 0.8],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const options = parseAnalyzeArgs(['--dump', 'd', '--cv-screen', '--log-weight', '0']);
    if (options.kind !== 'dump') throw new Error('expected a dump mode');
    const report = formatAnalyzeSections(cases, 'd', options);
    expect(report).toContain('Decisive-stability screen');
    expect(report).toContain('gain 1');
  });
});

/**
 * The frontier of a solved window, and the weight the report recommends.
 *
 * The window is the instrument that DECIDES which weight a benchmark run is dispatched at, so the
 * two things it must not do are (1) claim a gain at a weight its own arithmetic does not deliver,
 * and (2) present the claim without the margin that decides it. Both are asserted here.
 */
describe('the solved window reports a weight its own arithmetic delivers', () => {
  const WEIGHTS = { logWeight: 0, latWeight: 0, poolWeight: 0, temporalWeight: 0 } as const;

  it('reports the margin each gain has at the shipped weight, and the term\u2019s own step', () => {
    // The measurement this exists for: on the shipped dump run 35107871516 the screen reported
    // `gain 6` at 0.030170, and the run dispatched at that weight delivered FIVE (Top@1 756 to
    // 761, 53.2% to 53.5%, zero regressed fault types). The case it lost is the thinnest of the
    // six — margin 1.054e-4 against 3.129e-4 for the next — and one rank position of this term is
    // worth `ship / (services - 1)` = 6.034e-4, six times the margin that was load-bearing. A
    // report that prints the count and not the margin cannot be read at that resolution: the dump
    // renders every input at three decimals, so the base itself is only good to ~1e-3.
    //
    // The fixture is the smallest one whose gain is not a knife edge: the target is capped from
    // above by a faster rival AND floored by a slower one, so its admissible set is a real interval
    // and the recommended weight sits inside it rather than on its edge.
    const cases = [
      cvCase({
        cvs: [0.4, 0.9, 0.1],
        anomalies: [0.7, 0.9, 0.5],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const screen = cvScreen(cases, WEIGHTS, 'rank');
    const report = formatCvScreenReport(screen, WEIGHTS);

    expect(screen.solved.gain).toBe(1);
    expect(report).toContain('margin: thinnest');
    expect(report).toContain('one rank step');
    // The margin is quoted in the same units the report's other numbers are, and the quantum is
    // the term's own step for THIS case — not a constant, because it scales with the weight.
    const margin = screen.solved.margins[0]!;
    expect(margin.datapack).toBe('dp-1');
    expect(margin.margin).toBeGreaterThan(0);
    expect(margin.quantum).toBeCloseTo(screen.solved.ship / (margin.services - 1), 12);
    // The thinnest first, so a reader sees the frontier without scanning the list.
    for (let index = 1; index < screen.solved.margins.length; index++) {
      expect(screen.solved.margins[index]!.margin).toBeGreaterThanOrEqual(
        screen.solved.margins[index - 1]!.margin,
      );
    }
  });

  it('breaks a margin tie by datapack, so two runs of the dump compare', () => {
    // Two copies of one case have the same frontier by construction, so the tie-break is the only
    // thing deciding the order — and an order that followed the dump's file order instead would
    // make two runs of the same benchmark diff.
    const same = {
      cvs: [0.4, 0.9, 0.1],
      anomalies: [0.7, 0.9, 0.5],
      groundTruth: 'ts-svc-0',
      prediction: 'ts-svc-1',
    } as const;
    const screen = cvScreen(
      [cvCase({ ...same, datapack: 'dp-b' }), cvCase({ ...same, datapack: 'dp-a' })],
      WEIGHTS,
      'rank',
    );

    expect(screen.solved.gain).toBe(2);
    expect(screen.solved.margins.map((one) => one.datapack)).toEqual(['dp-a', 'dp-b']);
    expect(screen.solved.margins[0]!.margin).toEqual(screen.solved.margins[1]!.margin);
  });

  it('never recommends a weight that fails to satisfy a gain it lists', () => {
    // The invariant the whole profile exists for. Every datapack in `gained` must be satisfied AT
    // `ship`: the count and the weight are two halves of one claim, and a report whose midpoint
    // lands in a gap between two islands of one case's admissible set would state a gain that its
    // own interval arithmetic denies.
    const cases = [
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    const screen = cvScreen(cases, WEIGHTS, 'rank');
    const listed = new Set(screen.solved.gained);
    const covered = screen.solved.window.gains
      .filter((one) => listed.has(one.datapack))
      .filter((one) =>
        one.intervals.some(
          (interval) =>
            screen.solved.ship >= interval.min - 1e-12 &&
            screen.solved.ship <= interval.max + 1e-12,
        ),
      )
      .map((one) => one.datapack);

    expect([...covered].sort()).toEqual([...listed].sort());
    expect(screen.solved.gain).toBe(screen.solved.gained.length);
  });
});

describe('solveZeroRegressionWindow — the profile is a scan, not a cumulative count', () => {
  /** A case from plain numbers, so each fixture reads as arithmetic. */
  const affine = (
    datapack: string,
    targets: readonly string[],
    scores: Record<string, [number, number]>,
  ): WeightSeparationCase => ({
    datapack,
    targets,
    scores: new Map(Object.entries(scores).map(([id, [base, slope]]) => [id, { base, slope }])),
  });

  it('does NOT carry a gain past the end of its own admissible interval', () => {
    // `caseWeightInterval` returns a LIST because a case satisfied by either of two roots can be
    // satisfied over two disjoint weight ranges — the caller-visible contract this module already
    // tests. A profile that counts a gain from its floor upward reads that list as one half-line
    // and so claims the GAP as well, which is the same defect `mergeIntervals` exists to avoid one
    // layer down. The fixture: root `a` leads on [0.20, 0.30], the non-root `g` owns (0.30, 0.35),
    // and root `b` from 0.35, with a protector holding the window open to 0.44. The rule that
    // failed shipped 0.32 — the midpoint of the outer span, which is inside the gap, where its own
    // interval arithmetic says the case is NOT satisfied.
    const gain = affine('gain-two-islands', ['a', 'b'], {
      a: [0.6, 1],
      b: [-0.05, 3],
      g: [0.3, 2],
      c: [0.8, 0],
    });
    const protector = affine('protect', ['t'], { t: [0.9, 0], r: [0.46, 1] });
    const solved = solveZeroRegressionWindow([gain, protector]);

    const islands = caseWeightInterval(gain);
    expect(islands).toHaveLength(2);
    expect(islands[0]!.min).toBeCloseTo(0.2, 12);
    expect(islands[0]!.max).toBeCloseTo(0.3, 12);
    expect(islands[1]!.min).toBeCloseTo(0.35, 12);
    expect(islands[1]!.max).toBe(Number.POSITIVE_INFINITY);

    expect(solved.gain).toBe(1);
    // The profile steps DOWN between the two islands — a cumulative count over the floors could
    // only ever rise, so this sequence is the defect stated as an observable.
    const counts = solved.steps.map((step) => step.gained);
    const changes = counts.filter((count, index) => index === 0 || count !== counts[index - 1]!);
    expect(changes).toEqual([0, 1, 0, 1]);
    // The widest maximal-gain range is the FIRST island (0.10 wide against 0.09), so 0.25 is the
    // recommendation — and the gain is satisfied there, which is the invariant.
    expect(solved.gainFloor).toBeCloseTo(0.2, 12);
    expect(solved.bestEnd).toBeCloseTo(0.3, 12);
    expect(solved.ship).toBeCloseTo(0.25, 12);
    expect(solved.gained).toEqual(['gain-two-islands']);
    expect(solved.lostAtShip).toBe(0);
  });

  it('ships the midpoint of the WIDEST maximal-gain range, not of the span between them', () => {
    // Same structure, with the second island widened instead. The outer span [0.20, 0.60] has
    // midpoint 0.40 — the left edge of the second island, which happens to be satisfied — while
    // the widest maximal-gain range is [0.40, 0.60] and its midpoint is 0.50. The two rules
    // disagree here only in WHICH endpoint they trust; the assertion is that the plateau is what
    // is measured.
    const gain = affine('gain-wide-second', ['a', 'b'], {
      a: [0.6, 1],
      b: [-0.05, 3],
      g: [0.35, 2],
      c: [0.8, 0],
    });
    const protector = affine('protect', ['t'], { t: [0.9, 0], r: [0.3, 1] });
    const solved = solveZeroRegressionWindow([gain, protector]);

    expect(solved.gain).toBe(1);
    expect(solved.gainFloor).toBeCloseTo(0.4, 12);
    expect(solved.bestEnd).toBeCloseTo(0.6, 12);
    expect(solved.ship).toBeCloseTo(0.5, 12);
    expect(solved.gained).toEqual(['gain-wide-second']);
    expect(solved.lostAtShip).toBe(0);
  });
});

/**
 * What the dump's own rendering can decide.
 *
 * The screen's headline is a COUNT, and the inputs that count is computed from are printed by the
 * producer at a fixed number of decimals. That is a measurement error bar the screen never stated:
 * on the shipped dump the decisive-stability screen reported `gain 6` at 0.030170 and the run
 * dispatched at that weight collected five, with the lost case's lead (1.054e-4) an order of
 * magnitude below what the formatter can express. These tests hold the instrument to saying so.
 */
describe('gainResolution — the lead the formatter discards', () => {
  const WEIGHTS = { logWeight: 1, latWeight: 0, poolWeight: 0, temporalWeight: 0 } as const;

  /**
   * A two-service case whose lead is a fraction of the quantum: the target wins on the metric term
   * by `log1p(1)` = 0.693147 and loses `0.694` on the log term, so at 0.00086 it leads by 7.2e-6 —
   * smaller than the 5.0e-4 the formatter rounds `logScore` to.
   */
  const fixture = (extra: Partial<Parameters<typeof cvCase>[0]> = {}): DiagnosedCase =>
    cvCase({
      cvs: [0.1, 0.9],
      anomalies: [1.0, 0.5],
      logScores: [0, 0.694],
      groundTruth: 'ts-svc-0',
      prediction: 'ts-svc-1',
      ...extra,
    });

  const solve = (ship: number, cases: readonly DiagnosedCase[]) =>
    gainResolution({
      cases,
      gained: ['dp-1'],
      ship,
      screen: { kind: 'stability', weights: WEIGHTS, shape: 'rank' },
    });

  it('refuses to decide a gain whose lead is narrower than the quantum', () => {
    // The measurement this exists for. A gain inside the quantum is not a claim the dump supports:
    // the engine's own value could be on either side, so `gain 1` here means "somewhere in 0..1".
    const resolution = solve(0.00086, [fixture()]);

    expect(resolution.trials).toBe(GAIN_RESOLUTION_TRIALS);
    expect(resolution.resolved).toEqual([]);
    expect(resolution.least).toBe(0);
    expect(resolution.held[0]).toBeLessThan(resolution.trials);
    // Half the resamplings either way, which is what "not decided" means arithmetically.
    expect(resolution.held[0]).toBeGreaterThan(0);

    const line = formatResolutionLine(resolution);
    expect(line).toContain('0 of 1 gains hold in every one');
    // The bar is quoted from the producer's own precision, so a producer that prints more decimals
    // moves this number without anyone editing the analyzer.
    expect(line).toContain((2 * DUMP_HALF_QUANTUM).toExponential(1));
  });

  it('decides a gain whose lead is wider than the whole quantum', () => {
    // The other half of the same claim, and the reason this is a measurement rather than a
    // pessimism: at 0.003 the lead is 2.147e-3, wider than the 1.0e-3 a pairwise comparison of two
    // three-decimal numbers can move by, so NO draw in the box can flip it. The latency field is
    // present here, because a dump that measured no rise is a case the resampling must also carry.
    const resolution = solve(0.003, [fixture({ latRises: [1.5, 2.5] })]);

    expect(resolution.resolved).toEqual(['dp-1']);
    expect(resolution.least).toBe(1);
    expect(resolution.most).toBe(1);
    expect(resolution.histogram[1]).toBe(resolution.trials);
    expect(resolution.held[0]).toBe(resolution.trials);
    expect(formatResolutionLine(resolution)).toContain(
      `every one of the 1 gains holds in all ${GAIN_RESOLUTION_TRIALS} resamplings`,
    );
  });

  it('reports the same ensemble for the same dump, because the draw is seeded', () => {
    // A statistic that moves between two runs of the same dump is not a measurement of the dump.
    // The sequence is a declared constant, so the report is reproducible byte for byte — the
    // ensemble is a resampling of a KNOWN error bar, not an experiment.
    const first = solve(0.00086, [fixture()]);
    const second = solve(0.00086, [fixture()]);
    expect(JSON.stringify(second)).toBe(JSON.stringify(first));
  });

  it('derives its quantum from the producer rather than restating it', () => {
    // One owner. The analyzer cannot know the format from memory, and a second copy of `3` would
    // keep reporting 1.0e-3 the day the producer starts printing six decimals — which is exactly
    // how a resolution claim goes stale without a test failing.
    expect(SERVICE_FIELD_DECIMALS).toBe(3);
    expect(DUMP_HALF_QUANTUM).toBe(0.5 * 10 ** -SERVICE_FIELD_DECIMALS);
    const producer = readFileSync(
      new URL('../../packages/kinetic/src/benchmarks/fse26-diagnose.ts', import.meta.url),
      'utf-8',
    );
    expect(producer).toContain('toFixed(SERVICE_FIELD_DECIMALS)');
    expect(producer).not.toContain('toFixed(3)');
  });

  it('prints nothing for a window that gained nothing', () => {
    // The three screens call this only inside their `gain > 0` branch, so this is the contract for
    // a DIRECT caller: a distribution over no gain is not a measurement, and an empty histogram
    // rendered as text would read like one.
    expect(
      formatResolutionLine({
        trials: 4,
        histogram: [4],
        least: 0,
        most: 0,
        resolved: [],
        held: [],
      }),
    ).toBe('');
  });

  it('is printed by every screen that names a weight to ship', () => {
    // The wiring, asserted where a reader would notice its absence: a screen that recommends a
    // weight without saying what its own inputs can resolve is the defect this section exists for.
    // The onset screen needs an anchor and an ORDER before it has a window at all, so this fixture
    // carries both rather than asserting a line the term's own availability gate suppresses.
    const cases = [
      cvCase({
        cvs: [0.1, 0.9],
        anomalies: [1.0, 0.5],
        logScores: [0, 0.694],
        onsets: [120, 900],
        injectTimeMs: 1754685690000,
        // The family screen penalises services IN a family, so its gain needs the target and the
        // rival on different sides of that boundary — a second reason the fixture names them.
        dominants: ['cpu', 'http.server.request.duration.max'],
        groundTruth: 'ts-svc-0',
        prediction: 'ts-svc-1',
      }),
    ];
    expect(formatCvScreenReport(cvScreen(cases, WEIGHTS, 'rank'), WEIGHTS)).toContain(
      'resolution:',
    );
    expect(formatOnsetScreenReport(onsetScreen(cases, WEIGHTS, 'earliness'), WEIGHTS)).toContain(
      'resolution:',
    );
    expect(formatFamilyScreenReport(familyScreen(cases, WEIGHTS), WEIGHTS)).toContain(
      'resolution:',
    );
  });
});

/**
 * A weight the CALLER names, evaluated by the instrument that solved the window.
 *
 * The reopening condition this axis carries is two-sided and names a weight: "is candidate W
 * golden-neutral?" The screen could only answer the other question — "which weight is best here" —
 * so a veto arrived as an observation about a run ("4 of 9 cells moved") rather than as a per-case
 * account comparable, case for case, with the `+5 / 0 regressed types` the FSE'26 side reported. Same
 * instrument, same units: that is the whole point of evaluating a NAMED weight rather than a solved
 * one.
 */
describe('a named weight, evaluated per case', () => {
  /** A case from plain numbers, so each fixture reads as arithmetic. */
  const affine = (
    datapack: string,
    targets: readonly string[],
    scores: Record<string, [number, number]>,
  ): WeightSeparationCase => ({
    datapack,
    targets,
    scores: new Map(Object.entries(scores).map(([id, [base, slope]]) => [id, { base, slope }])),
  });

  /**
   * Root `a` leads on `[0.20, 0.30]` and `b` from `0.35` — a gain with two islands, so a weight in
   * the gap is a weight at which the case is NOT fixed. `protect` is correct at 0 and stays correct
   * only to 0.44, so a weight past it is a LOSS: the fixture can hold a gain and a loss at once,
   * which is the shape a veto has.
   */
  const gain = (): WeightSeparationCase =>
    affine('gain-two-islands', ['a', 'b'], {
      a: [0.6, 1],
      b: [-0.05, 3],
      g: [0.3, 2],
      c: [0.8, 0],
    });
  const protector = (): WeightSeparationCase =>
    affine('protect', ['t'], { t: [0.9, 0], r: [0.46, 1] });

  it('reports correct, gained and lost at the named weight, and NAMES the losses', () => {
    // A count is not a verdict: `lost 1` decides the criterion, but WHICH case was lost is what a
    // reader has to check — the same reason the pool penalty's window names its cap binder.
    const solved = solveZeroRegressionWindow([gain(), protector()], 0.5);

    expect(solved.at).toBeDefined();
    expect(solved.at!.weight).toBe(0.5);
    expect(solved.at!.gained).toBe(1);
    expect(solved.at!.lost).toBe(1);
    expect(solved.at!.correct).toBe(1);
    expect(solved.at!.gainedDatapacks).toEqual(['gain-two-islands']);
    expect(solved.at!.lostDatapacks).toEqual(['protect']);
    // The solved recommendation is untouched by the question: this is a second reading of the same
    // window, not a re-solve that could move the weight the screen would have shipped.
    expect(solved.ship).toBeCloseTo(0.25, 12);
    expect(solved.gain).toBe(1);
  });

  it('is absent when no weight is named, so nothing about the default report moves', () => {
    const solved = solveZeroRegressionWindow([gain(), protector()]);
    expect(solved.at).toBeUndefined();
  });

  it('counts a weight inside the gain island as a gain with no loss', () => {
    const solved = solveZeroRegressionWindow([gain(), protector()], 0.25);
    expect(solved.at!.gained).toBe(1);
    expect(solved.at!.lost).toBe(0);
    expect(solved.at!.lostDatapacks).toEqual([]);
    expect(solved.at!.correct).toBe(2);
  });

  it('reports a gain of zero in the gap between the case’s own islands', () => {
    // 0.32 is inside `[0.20, 0.30] ∪ [0.35, ∞)`'s gap, so the case is untouched there. An instrument
    // that read the union as one half-line would report it as gained — the defect this module's
    // profile fix was about, now reachable through a second door.
    const solved = solveZeroRegressionWindow([gain(), protector()], 0.32);
    expect(solved.at!.gained).toBe(0);
    expect(solved.at!.gainedDatapacks).toEqual([]);
    expect(solved.at!.lost).toBe(0);
    expect(solved.at!.correct).toBe(1);
  });

  it('prints the block with the count and the names, and nothing when no weight was named', () => {
    // A weight past the case's own cap, so the block reports a real loss and names the case that
    // paid for it. The cap is where the rival overtakes: with a lead of 0.693147 and a slope gap of
    // 1.0 it sits at 0.693147, so 1.0 is past it whatever the numbers are set to.
    const fixture = () =>
      cvCase({
        cvs: [0.1, 0.6],
        anomalies: [0.5, 0.9],
        groundTruth: 'ts-svc-1',
        prediction: 'ts-svc-1',
      });
    const named = formatCvScreenReport(cvScreen([fixture()], { logWeight: 1 }, 'rank', 1), {
      logWeight: 1,
    });

    expect(named).toContain('at 1.000000');
    expect(named).toContain('lost 1');
    expect(named).toContain('lost: dp-1');

    const unnamed = formatCvScreenReport(cvScreen([fixture()], { logWeight: 1 }, 'rank'), {
      logWeight: 1,
    });
    expect(unnamed).not.toContain(' at 1.000000');
  });
});

describe('a named weight reaches every report that solves a window', () => {
  const WEIGHTS = { logWeight: 1, latWeight: 0, poolWeight: 0, temporalWeight: 0 } as const;

  /**
   * A case the window has NO gain on, and a named weight that LOSES it.
   *
   * Service 1 is the ground truth and leads on the metric term at `w = 0`; it is also the LEAST
   * stable one, so the term's slope belongs to service 0 and any positive weight overtakes it at
   * 0.2364. Gain 0, lost 1 at `w = 0.5` — the exact shape of a veto, and the shape both menus would
   * otherwise print nothing about.
   */
  const losing = (): DiagnosedCase =>
    cvCase({
      cvs: [0.1, 0.6],
      anomalies: [0.5, 0.9],
      groundTruth: 'ts-svc-1',
      prediction: 'ts-svc-1',
    });

  it('is printed by the cv MENU even when the shape has no gain at any weight', () => {
    // The trap: both menus printed a shape's detail only `if (s.gain > 0)`, so a named weight that
    // gains nothing — precisely the case where a reader would conclude "harmless" — was rendered
    // NOWHERE. The single-screen formatter had it and the menu, which is what the CLI prints, did not.
    const menu = formatCvMenuReport(cvShapeMenu([losing()], WEIGHTS, 1), WEIGHTS);

    expect(menu).toContain(' at 1.000000');
    expect(menu).toContain('lost 1');
    expect(menu).toContain('lost: dp-1');
    // And the same verdict is what the single-screen formatter prints, so the two cannot disagree.
    expect(formatCvScreenReport(cvScreen([losing()], WEIGHTS, 'rank', 1), WEIGHTS)).toContain(
      ' at 1.000000',
    );
  });

  it('names a GAIN and no loss when the named weight only helps', () => {
    // The positive counterpart of the veto, and the branch the other fixtures leave uncovered: a
    // weight that fixes a case and costs none. It prints `gained:` and no `lost:` line — which is
    // what a reader is looking for, and the reason the two lists are printed independently rather
    // than as one "changed" list.
    // The target is the MOST stable service (cv 0.1, so its slope is 1) and behind on the metric
    // term by 0.5466, so a weight of 1 overtakes the rival. Nothing was correct at 0, so nothing can
    // be lost.
    const helping = cvCase({
      cvs: [0.6, 0.1],
      anomalies: [0.9, 0.1],
      groundTruth: 'ts-svc-1',
      prediction: 'ts-svc-0',
    });
    const report = formatCvScreenReport(cvScreen([helping], WEIGHTS, 'rank', 1), WEIGHTS);

    expect(report).toContain('at 1.000000');
    expect(report).toContain('gained 1');
    expect(report).toContain('lost 0');
    expect(report).toContain('gained: dp-1');
    expect(report).not.toContain('    lost:');
  });

  it('survives a dump where the term is INERT, which is the menu’s other early exit', () => {
    // The second trap, found by probing rather than by reading: the menus return as soon as they
    // learn the term cannot act, BEFORE the loops that render a shape's detail — so on an inert dump
    // the flag was dropped a second time, and an inert dump is exactly where "the weight changes
    // nothing" is the tempting conclusion. `losing()` carries no onset delays, which is what makes
    // the temporal screen inert.
    const menu = formatOnsetMenuReport(onsetShapeMenu([losing()], WEIGHTS, 1), WEIGHTS);

    expect(menu).toContain('the term is INERT');
    expect(menu).toContain(' at 1.000000');
  });

  it('is parsed from --at-weight, and refused when no screen would print it', () => {
    // A flag that is accepted and rendered nowhere is how a flag becomes ritual: the file's own
    // `log-weight` rule, applied to the other side of the same question.
    const dumpMode = (argv: readonly string[]) => {
      const opts = parseAnalyzeArgs(['--dump', 'd.txt', ...argv]);
      if (opts.kind !== 'dump') throw new Error('expected dump mode');
      return opts;
    };

    const opts = dumpMode(['--log-weight', '1', '--cv-screen', '--at-weight', '0.03017']);
    expect(opts.sections[0]!.atWeight).toBe(0.03017);
    // Absent, not 0: the default report must be the one it was before the flag existed.
    expect(dumpMode(['--log-weight', '1', '--cv-screen']).sections[0]!.atWeight).toBeUndefined();

    expect(() => dumpMode(['--log-weight', '1', '--cv-screen', '--at-weight', 'oops'])).toThrow(
      /at-weight/,
    );
    expect(() => dumpMode(['--log-weight', '1', '--cv-screen', '--at-weight', '-1'])).toThrow(
      /at-weight/,
    );
    expect(() => dumpMode(['--log-weight', '1', '--misses', '--at-weight', '0.03'])).toThrow(
      /cv-screen/,
    );
  });
});
